const crypto = require('crypto');
const item = $input.first().json;

const h = {};
for (const [k, v] of Object.entries(item.headers || {})) h[k.toLowerCase()] = v;

let secret = '';
try { secret = String($env.GITHUB_WEBHOOK_SECRET || ''); } catch (e) { secret = ''; }

let valid = false;
let reason = '';
if (!secret) {
  reason = 'GITHUB_WEBHOOK_SECRET is not available to the Code node';
} else {
  try {
    const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
    const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
    const a = Buffer.from(expected);
    const b = Buffer.from(String(h['x-hub-signature-256'] || ''));
    valid = a.length === b.length && crypto.timingSafeEqual(a, b);
    if (!valid) reason = 'signature mismatch';
  } catch (e) {
    reason = 'raw body unavailable: ' + e.message;
  }
}

return [{ json: {
  valid, reason,
  event: String(h['x-github-event'] || ''),
  delivery: String(h['x-github-delivery'] || ''),
  payload: item.body || {}
} }];

const v = $('Verify Signature').first().json;
const p = v.payload || {};
const pr = p.pull_request || {};

// Optional allow-list, e.g. ['my-org/api', 'my-org/web']. Empty means every repository that can reach this webhook.
const ALLOWED_REPOS = [];
const ACTIONS = ['opened', 'synchronize', 'reopened', 'ready_for_review'];

const repo = String((p.repository && p.repository.full_name) || '');
const labels = (pr.labels || []).map(l => String((l && l.name) || '').toLowerCase());

let reason = '';
if (v.event === 'ping') reason = 'ping event';
else if (v.event !== 'pull_request') reason = 'event "' + v.event + '" is ignored';
else if (!ACTIONS.includes(p.action)) reason = 'action "' + p.action + '" is ignored';
else if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo)) reason = 'invalid repository name';
else if (ALLOWED_REPOS.length && !ALLOWED_REPOS.includes(repo)) reason = 'repository is not in the allow-list';
else if (pr.draft) reason = 'draft pull request';
else if (labels.includes('skip-ai-review')) reason = 'label skip-ai-review';
else if (pr.user && pr.user.type === 'Bot') reason = 'pull request opened by a bot';
else if (!pr.number || !(pr.head && pr.head.sha)) reason = 'incomplete payload';

return [{ json: {
  skip: reason !== '',
  reason,
  repo,
  pr_number: Number(pr.number) || 0,
  title: String(pr.title || '').slice(0, 200),
  author: String((pr.user && pr.user.login) || ''),
  base: String((pr.base && pr.base.ref) || ''),
  head_sha: String((pr.head && pr.head.sha) || ''),
  html_url: String(pr.html_url || ''),
  body: String(pr.body || '').slice(0, 2000),
  delivery: v.delivery
} }];

const ctx = $('Parse PR Event').first().json;
const raw = $input.first().json || {};
const diff = typeof raw.diff === 'string' ? raw.diff : (typeof raw.data === 'string' ? raw.data : '');

const SKIP_PATH = [
  /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|poetry\.lock|Pipfile\.lock|composer\.lock|Gemfile\.lock|Cargo\.lock|go\.sum)$/,
  /\.min\.(js|css)$/, /\.map$/, /(^|\/)(dist|build|vendor|node_modules|\.next|coverage)\//,
  /\.(png|jpe?g|gif|webp|ico|svg|pdf|zip|gz|woff2?|ttf|eot|mp4|mov)$/i
];
// Specific patterns first, the generic one last. Only the first match per line is reported.
const SECRET_PATTERNS = [
  ['AWS access key ID', /AKIA[0-9A-Z]{16}/g],
  ['private key', /-----BEGIN (?:RSA |EC |DSA |OPENSSH |PGP )?PRIVATE KEY-----/g],
  ['GitHub token', /gh[pousr]_[A-Za-z0-9]{36,}/g],
  ['Slack token', /xox[baprs]-[A-Za-z0-9-]{10,}/g],
  ['Google API key', /AIza[0-9A-Za-z_-]{35}/g],
  ['OpenAI-style API key', /sk-[A-Za-z0-9_-]{32,}/g],
  ['hard-coded credential', /(?:api[_-]?key|secret|passw(?:or)?d|token)\s*[:=]\s*['"][^'"\s]{12,}['"]/gi]
];
const MAX_FILE = 6000;
const MAX_TOTAL = 30000;

const base = {
  repo: ctx.repo, pr_number: ctx.pr_number, title: ctx.title, author: ctx.author, base: ctx.base,
  head_sha: ctx.head_sha, html_url: ctx.html_url, body: ctx.body
};

if (!diff.trim()) {
  return [{ json: { ...base, has_changes: false, fetch_failed: true, diff_for_llm: '', files_reviewed: [], files_skipped: [], secrets: [], additions: 0, deletions: 0, truncated: false } }];
}

const chunks = diff.split(/^diff --git /m).filter(c => c.trim());
const reviewed = [], skipped = [], secrets = [], out = [];
let additions = 0, deletions = 0, total = 0, truncated = false;

for (const chunk of chunks) {
  const lines = chunk.split('\n');
  const m = (lines[0] || '').match(/^a\/(.+?) b\/(.+)$/);
  const path = m ? m[2] : (lines[0] || '').trim();
  const isBinary = /^Binary files |^GIT binary patch/m.test(chunk);

  let inHunk = false, newLine = 0;
  const kept = [];
  for (const line of lines.slice(1)) {
    const h = line.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (h) { inHunk = true; newLine = parseInt(h[1], 10); kept.push(line); continue; }
    if (!inHunk) { kept.push(line); continue; }
    if (line.startsWith('+')) {
      additions++;
      let text = line;
      if (!isBinary) {
        for (const [type, re] of SECRET_PATTERNS) {
          if (line.slice(1).match(re)) {
            secrets.push({ file: path, line: newLine, type });
            text = '+' + line.slice(1).replace(re, '[REDACTED]');
            break;
          }
        }
        for (const [, re] of SECRET_PATTERNS) text = text.replace(re, '[REDACTED]');
      }
      kept.push(text);
      newLine++;
    } else if (line.startsWith('-')) {
      deletions++;
      kept.push(line);
    } else {
      kept.push(line);
      if (!line.startsWith('\\')) newLine++;
    }
  }

  if (isBinary) { skipped.push({ path, reason: 'binary file' }); continue; }
  if (SKIP_PATH.some(re => re.test(path))) { skipped.push({ path, reason: 'generated, vendored, or lock file' }); continue; }

  let body = kept.join('\n');
  if (body.length > MAX_FILE) { body = body.slice(0, MAX_FILE) + '\n[... file diff truncated ...]'; truncated = true; }
  const block = '### FILE: ' + path + '\n' + body;
  if (total + block.length > MAX_TOTAL) { skipped.push({ path, reason: 'diff size limit reached' }); truncated = true; continue; }
  total += block.length;
  out.push(block);
  reviewed.push(path);
}

return [{ json: {
  ...base,
  has_changes: reviewed.length > 0,
  fetch_failed: false,
  diff_for_llm: out.join('\n\n'),
  files_reviewed: reviewed,
  files_skipped: skipped,
  secrets, additions, deletions, truncated
} }];

const d = $input.first().json;
if (!d.fetch_failed) return [];
return [{ json: { text: 'PR review skipped for ' + d.repo + '#' + d.pr_number + ': the diff could not be fetched (very large pull request or GitHub API error).' } }];

