const d = $('Prepare Diff').first().json;
const raw = $input.first().json || {};

let c = raw.output ?? raw.text ?? raw.response ?? null;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { c = null; } }
if (c && c.output && typeof c.output === 'object') c = c.output;

const RISKS = ['low', 'medium', 'high'];
const SEVERITIES = ['blocker', 'warning', 'nit'];
const CATEGORIES = ['bug', 'security', 'performance', 'error_handling', 'tests', 'maintainability', 'docs'];
const MARKER = '<!-- ai-pr-review -->';

// LLM text is untrusted: no HTML, no @mentions, no backticks, one line.
const esc = s => String(s == null ? '' : s)
  .replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/@(?=[A-Za-z0-9_-])/g, '@​')
  .replace(/`/g, "'")
  .replace(/[\r\n]+/g, ' ')
  .trim();

const valid = !!c && typeof c === 'object' && typeof c.summary === 'string' &&
  RISKS.includes(c.risk_level) && Array.isArray(c.findings);
const llmFailed = !valid;

const files = new Set(d.files_reviewed || []);
const rank = { low: 0, medium: 1, high: 2 };
const sevRank = { blocker: 0, warning: 1, nit: 2 };

const findings = (valid ? c.findings : [])
  .filter(f => f && files.has(f.file) && SEVERITIES.includes(f.severity) && CATEGORIES.includes(f.category) && String(f.message || '').trim())
  .map(f => ({
    file: f.file,
    line: Number.isInteger(f.line) && f.line > 0 ? f.line : null,
    severity: f.severity,
    category: f.category,
    message: esc(f.message).slice(0, 600),
    suggestion: esc(f.suggestion).slice(0, 600)
  }))
  .sort((a, b) => sevRank[a.severity] - sevRank[b.severity])
  .slice(0, 12);

const count = s => findings.filter(f => f.severity === s).length;
const blockers = count('blocker'), warnings = count('warning'), nits = count('nit');
const secrets = d.secrets || [];

// Rules can only raise risk, never lower it.
let risk = valid ? c.risk_level : 'unknown';
if (secrets.length > 0 || blockers > 0) risk = 'high';

const post = secrets.length > 0 || valid;

let md = MARKER + '\n## AI Review (advisory)\n\n';
if (llmFailed) {
  md += '**The AI review could not be completed.** Only the automatic secret scan ran.\n\n';
} else {
  md += '**Risk: ' + risk.toUpperCase() + '** | ' + blockers + ' blocker(s) | ' + warnings + ' warning(s) | ' + nits + ' nit(s)\n\n';
  md += '> ' + esc(c.summary).slice(0, 500) + '\n\n';
}
if (secrets.length) {
  md += '### Possible secrets detected\n';
  md += secrets.slice(0, 20).map(s => '- `' + s.file + ':' + s.line + '` ' + s.type + '. Rotate it and remove it from git history.').join('\n') + '\n\n';
}
if (findings.length) {
  const titles = { blocker: 'Blockers', warning: 'Warnings', nit: 'Nits' };
  for (const sev of SEVERITIES) {
    const group = findings.filter(f => f.severity === sev);
    if (!group.length) continue;
    md += '### ' + titles[sev] + '\n';
    md += group.map(f => '- **`' + f.file + (f.line ? ':' + f.line : '') + '`** [' + f.category + '] ' + f.message + (f.suggestion ? '\n  - _Suggestion:_ ' + f.suggestion : '')).join('\n') + '\n\n';
  }
} else if (valid && secrets.length === 0) {
  md += 'No issues found in the reviewed changes.\n\n';
}
const skippedCount = (d.files_skipped || []).length;
md += '<sub>Commit `' + String(d.head_sha).slice(0, 7) + '` | ' + files.size + ' file(s) reviewed' +
  (skippedCount ? ', ' + skippedCount + ' skipped' : '') + (d.truncated ? ' (diff truncated)' : '') +
  ' | Automated and advisory. Line numbers are approximate and findings may be wrong.</sub>';

return [{ json: {
  post,
  comment_body: md.slice(0, 60000),
  risk_level: risk,
  findings_count: findings.length,
  blockers, warnings, nits,
  secrets_found: secrets.length,
  llm_failed: llmFailed,
  needs_alert: risk === 'high' || blockers > 0 || secrets.length > 0
} }];

const built = $('Build Review Comment').first().json;
const MARKER = '<!-- ai-pr-review -->';
const existing = $input.all()
  .map(i => i.json)
  .find(cm => cm && typeof cm.body === 'string' && cm.body.includes(MARKER) && cm.id);
return [{ json: { existing_id: existing ? existing.id : null, has_existing: !!existing, comment_body: built.comment_body } }];

const d = $('Prepare Diff').first().json;
const b = $('Build Review Comment').first().json;
const label = b.risk_level === 'high' ? 'HIGH RISK' : b.risk_level.toUpperCase();
let t = 'PR REVIEW - ' + label + '\n\n';
t += d.repo + '#' + d.pr_number + ': ' + d.title + '\n';
t += 'by ' + d.author + ' into ' + d.base + '\n\n';
t += 'Blockers: ' + b.blockers + ' | Warnings: ' + b.warnings + ' | Possible secrets: ' + b.secrets_found + '\n';
t += d.html_url;
return [{ json: { text: t } }];

const monitors = $input.all().map(i => i.json).filter(m => m && m.id);
const BATCH = 10;

const check = async (m) => {
  const started = Date.now();
  const expected = Number(m.expected_status) || 200;
  try {
    if (!/^https?:\/\//i.test(String(m.url || ''))) throw new Error('Invalid URL (must start with http:// or https://)');
    const res = await this.helpers.httpRequest({
      method: 'GET', url: m.url, timeout: Number(m.timeout_ms) || 10000,
      returnFullResponse: true, ignoreHttpStatusErrors: true
    });
    const latency = Date.now() - started;
    const status = Number(res.statusCode);
    let ok = status === expected;
    let error = ok ? '' : 'Expected HTTP ' + expected + ' but got ' + status;
    if (ok && m.expected_text) {
      const body = typeof res.body === 'string' ? res.body : JSON.stringify(res.body || '');
      if (!body.includes(m.expected_text)) { ok = false; error = 'Response did not contain the expected text'; }
    }
    return { id: m.id, ok, status_code: Number.isFinite(status) ? status : null, latency_ms: latency, error };
  } catch (e) {
    return { id: m.id, ok: false, status_code: null, latency_ms: Date.now() - started, error: String((e && e.message) || e).slice(0, 300) };
  }
};

const results = [];
for (let i = 0; i < monitors.length; i += BATCH) {
  results.push(...await Promise.all(monitors.slice(i, i + BATCH).map(check)));
}
return [{ json: { results_json: JSON.stringify(results), count: results.length } }];

const rows = $input.all().map(i => i.json);
const parts = [];
for (const r of rows.filter(x => x.event === 'down')) {
  parts.push('DOWN: ' + r.name + '\n' + r.url + '\nReason: ' + (r.error || 'unknown') + '\nFailed ' + r.consecutive_failures + ' check(s) in a row');
}
for (const r of rows.filter(x => x.event === 'recovered')) {
  const mins = r.downtime_minutes == null ? NaN : Number(r.downtime_minutes);
  parts.push('RECOVERED: ' + r.name + '\n' + r.url + '\nDowntime: ' + (Number.isFinite(mins) ? '~' + mins + ' min' : 'unknown'));
}
return [{ json: { text: parts.join('\n\n') } }];

const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { text: 'WORKFLOW ERROR\n\nWorkflow: ' + wf + '\nFailed node: ' + node + '\nError: ' + String(msg).slice(0, 500) + (url ? '\n' + url : '') } }];
